"use client";

import { useState, useRef, useCallback, useEffect, useReducer } from "react";

export interface ResizablePanelOptions {
  storageKey: string;
  defaultWidth: number;
  minWidth: number;
  maxWidthFraction: number;
  /** Arrow-key step in px (Shift uses `largeStep`). */
  step?: number;
  largeStep?: number;
}

export interface ResizablePanelResult {
  width: number;
  collapsed: boolean;
  containerRef: React.RefObject<HTMLDivElement | null>;
  handleProps: {
    onPointerDown: (e: React.PointerEvent) => void;
    onPointerMove: (e: React.PointerEvent) => void;
    onPointerUp: (e: React.PointerEvent) => void;
    onPointerCancel: (e: React.PointerEvent) => void;
    onKeyDown: (e: React.KeyboardEvent) => void;
    role: "separator";
    "aria-orientation": "vertical";
    "aria-label": string;
    tabIndex: 0;
    "aria-valuenow": number;
    "aria-valuemin": number;
    "aria-valuemax": number;
  };
  collapse: () => void;
  expand: () => void;
}

function readStoredNumber(key: string, fallback: number, min: number): number {
  if (typeof localStorage === "undefined") return fallback;
  try {
    const v = localStorage.getItem(key);
    if (v !== null) {
      const n = Number(v);
      if (!isNaN(n)) return Math.max(min, n);
    }
  } catch {
    // ignore
  }
  return fallback;
}

function readStoredBool(key: string, fallback: boolean): boolean {
  if (typeof localStorage === "undefined") return fallback;
  try {
    const v = localStorage.getItem(key);
    if (v !== null) return v === "true";
  } catch {
    // ignore
  }
  return fallback;
}

export function useResizablePanel({
  storageKey,
  defaultWidth,
  minWidth,
  maxWidthFraction,
  step = 16,
  largeStep = 64,
}: ResizablePanelOptions): ResizablePanelResult {
  const collapsedKey = storageKey + "Collapsed";

  const [width, setWidth] = useState<number>(() =>
    readStoredNumber(storageKey, defaultWidth, minWidth)
  );
  const [collapsed, setCollapsed] = useState<boolean>(() =>
    readStoredBool(collapsedKey, false)
  );

  const containerRef = useRef<HTMLDivElement>(null);
  // `aria-valuemax` reads the container width at render; the ref is empty on the first render, so re-render once
  // the container is measured and whenever it resizes.
  const [, remeasure] = useReducer((n: number) => n + 1, 0);
  const isDraggingRef = useRef(false);
  const lastWidthRef = useRef<number>(readStoredNumber(storageKey, defaultWidth, minWidth));
  const rafRef = useRef<number | null>(null);
  const pendingWidthRef = useRef<number | null>(null);

  // Persist width changes to localStorage
  useEffect(() => {
    try {
      localStorage.setItem(storageKey, String(width));
    } catch {
      // ignore
    }
  }, [storageKey, width]);

  // Persist collapsed changes to localStorage
  useEffect(() => {
    try {
      localStorage.setItem(collapsedKey, String(collapsed));
    } catch {
      // ignore
    }
  }, [collapsedKey, collapsed]);

  // Clamp width against the actual container size after mount — guards against
  // a stored value that exceeds maxWidthFraction on a narrower viewport.
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    const maxWidth = container.clientWidth * maxWidthFraction;
    if (maxWidth > 0 && width > maxWidth) {
      setWidth(maxWidth);
    }
  }, [maxWidthFraction]); // intentionally omits width — runs once on mount per fraction change

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    remeasure();
    if (typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => remeasure());
    observer.observe(container);
    return () => observer.disconnect();
  }, []);

  const onPointerDown = useCallback((e: React.PointerEvent) => {
    e.preventDefault();
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    isDraggingRef.current = true;
  }, []);

  const onPointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (!isDraggingRef.current) return;
      const container = containerRef.current;
      if (!container) return;

      const rect = container.getBoundingClientRect();
      const rawWidth = e.clientX - rect.left;
      const maxWidth = container.clientWidth * maxWidthFraction;
      const clamped = Math.max(minWidth, Math.min(maxWidth, rawWidth));

      pendingWidthRef.current = clamped;

      if (rafRef.current === null) {
        rafRef.current = requestAnimationFrame(() => {
          if (pendingWidthRef.current !== null) {
            setWidth(pendingWidthRef.current);
            pendingWidthRef.current = null;
          }
          rafRef.current = null;
        });
      }
    },
    [minWidth, maxWidthFraction]
  );

  const onPointerUp = useCallback((e: React.PointerEvent) => {
    isDraggingRef.current = false;
    (e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId);
    if (rafRef.current !== null) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    }
  }, []);

  const maxPx = () => (containerRef.current?.clientWidth ?? 0) * maxWidthFraction;

  // The separator pattern: Arrow keys step, Shift+Arrow takes a large step, Home/End jump to the drag bounds.
  const onKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      const max = maxPx();
      const dir = e.key === "ArrowRight" ? 1 : e.key === "ArrowLeft" ? -1 : 0;
      if (!dir && e.key !== "Home" && e.key !== "End") return;
      e.preventDefault();
      setWidth((w) => {
        const raw = e.key === "Home" ? minWidth : e.key === "End" ? max : w + dir * (e.shiftKey ? largeStep : step);
        return Math.max(minWidth, max > 0 ? Math.min(max, raw) : raw);
      });
    },
    // maxPx reads refs only
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [minWidth, maxWidthFraction, step, largeStep]
  );

  const collapse = useCallback(() => {
    lastWidthRef.current = width;
    setCollapsed(true);
  }, [width]);

  const expand = useCallback(() => {
    setCollapsed(false);
    setWidth(lastWidthRef.current || defaultWidth);
  }, [defaultWidth]);

  return {
    width,
    collapsed,
    containerRef,
    handleProps: {
      onPointerDown,
      onPointerMove,
      onPointerUp,
      onPointerCancel: onPointerUp,
      onKeyDown,
      role: "separator",
      "aria-orientation": "vertical",
      "aria-label": "Resize file panel",
      tabIndex: 0,
      "aria-valuenow": Math.round(width),
      "aria-valuemin": minWidth,
      "aria-valuemax": Math.round(Math.max(maxPx(), minWidth)),
    },
    collapse,
    expand,
  };
}
