'use client';
import { useEffect, useRef, useState } from 'react';

export interface CDPViewerProps {
  wsUrl: string;
  isVisible: boolean;
  onConnected?: () => void;
  onDisconnected?: () => void;
  /** When true, clicks are reported via onInspectClick instead of being sent to Chrome. */
  inspectMode?: boolean;
  /** Called with Chrome-pixel coordinates when the canvas is clicked in inspect mode. */
  onInspectClick?: (x: number, y: number) => void;
}

// Approximate hover box (Chrome pixels). The exact element box is only known
// after a click, so this is a cursor cue, not a selector.
const HOVER_BOX_W = 120;
const HOVER_BOX_H = 60;

// CDPViewer connects to a WebSocket that streams JPEG frames (binary messages)
// and renders them to a canvas. Mouse and keyboard events are forwarded back
// to the server as CDP Input.dispatch* JSON messages.
export default function CDPViewer({ wsUrl, isVisible, onConnected, onDisconnected, inspectMode = false, onInspectClick }: CDPViewerProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const overlayRef = useRef<HTMLCanvasElement>(null);
  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const unmountedRef = useRef(false);
  // Keep latest callbacks in a ref so they can be used in stable event handlers
  const onConnectedRef = useRef(onConnected);
  const onDisconnectedRef = useRef(onDisconnected);
  const isVisibleRef = useRef(isVisible);
  const [connectionStatusText, setConnectionStatusText] = useState<string>('Browser disconnected');

  useEffect(() => { onConnectedRef.current = onConnected; }, [onConnected]);
  useEffect(() => { onDisconnectedRef.current = onDisconnected; }, [onDisconnected]);
  useEffect(() => { isVisibleRef.current = isVisible; }, [isVisible]);

  // Leaving inspect mode clears any hover rectangle left on the overlay.
  const wasInspectingRef = useRef(false);
  useEffect(() => {
    if (wasInspectingRef.current && !inspectMode) clearOverlay();
    wasInspectingRef.current = inspectMode;
  }, [inspectMode]);

  // ------------------------------------------------------------------
  // WebSocket lifecycle
  // ------------------------------------------------------------------

  useEffect(() => {
    unmountedRef.current = false;

    // renderFrame only accesses canvasRef (a stable ref) so it does not need
    // to be listed in the effect's dependency array.
    async function renderFrame(data: ArrayBuffer) {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      if (typeof createImageBitmap !== 'undefined') {
        // Fast path: use createImageBitmap (supported in modern browsers)
        const blob = new Blob([data], { type: 'image/jpeg' });
        try {
          const bitmap = await createImageBitmap(blob);
          canvas.width = bitmap.width;
          canvas.height = bitmap.height;
          ctx.drawImage(bitmap, 0, 0);
          bitmap.close();
        } catch {
          // Ignore decode errors on individual frames
        }
      } else {
        // Fallback: use an Image element
        const blob = new Blob([data], { type: 'image/jpeg' });
        const url = URL.createObjectURL(blob);
        const img = new Image();
        img.onload = () => {
          canvas.width = img.naturalWidth;
          canvas.height = img.naturalHeight;
          ctx.drawImage(img, 0, 0);
          URL.revokeObjectURL(url);
        };
        img.onerror = () => URL.revokeObjectURL(url);
        img.src = url;
      }
    }

    function connect() {
      if (unmountedRef.current) return;

      const ws = new WebSocket(wsUrl);
      ws.binaryType = 'arraybuffer';
      wsRef.current = ws;

      ws.addEventListener('open', () => {
        if (unmountedRef.current) { ws.close(); return; }
        setConnectionStatusText('Browser connected');
        onConnectedRef.current?.();
      });

      ws.addEventListener('message', (event: MessageEvent) => {
        if (event.data instanceof ArrayBuffer) {
          void renderFrame(event.data);
        }
        // Text messages from server (status, etc.) are intentionally ignored
      });

      ws.addEventListener('close', () => {
        wsRef.current = null;
        setConnectionStatusText('Reconnecting to browser…');
        onDisconnectedRef.current?.();
        if (!unmountedRef.current) {
          // Reconnect with 2 s backoff
          reconnectTimerRef.current = setTimeout(connect, 2000);
        }
      });

      ws.addEventListener('error', () => {
        // Error is always followed by a close event; let close handle reconnection
      });
    }

    connect();

    return () => {
      unmountedRef.current = true;
      if (reconnectTimerRef.current !== null) {
        clearTimeout(reconnectTimerRef.current);
        reconnectTimerRef.current = null;
      }
      if (wsRef.current) {
        wsRef.current.close();
        wsRef.current = null;
      }
    };
  }, [wsUrl]);

  // ------------------------------------------------------------------
  // Input event helpers
  // ------------------------------------------------------------------

  function sendJson(obj: unknown) {
    const ws = wsRef.current;
    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify(obj));
    }
  }

  function getCanvasCoords(e: React.MouseEvent<HTMLCanvasElement>) {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    // Scale CSS pixels → Chrome device pixels using canvas intrinsic size
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    return {
      x: Math.round((e.clientX - rect.left) * scaleX),
      y: Math.round((e.clientY - rect.top) * scaleY),
    };
  }

  function getModifiers(e: React.MouseEvent | React.KeyboardEvent | React.WheelEvent): number {
    // CDP modifier bitmask: Alt=1, Ctrl=2, Meta/Cmd=4, Shift=8
    let m = 0;
    if (e.altKey) m |= 1;
    if (e.ctrlKey) m |= 2;
    if (e.metaKey) m |= 4;
    if (e.shiftKey) m |= 8;
    return m;
  }

  function cdpButton(e: React.MouseEvent): 'left' | 'right' | 'middle' | 'none' {
    switch (e.button) {
      case 0: return 'left';
      case 1: return 'middle';
      case 2: return 'right';
      default: return 'none';
    }
  }

  // ------------------------------------------------------------------
  // Mouse handlers
  // ------------------------------------------------------------------

  function clearOverlay() {
    const overlay = overlayRef.current;
    overlay?.getContext('2d')?.clearRect(0, 0, overlay.width, overlay.height);
  }

  function drawHoverBox(x: number, y: number) {
    const canvas = canvasRef.current;
    const overlay = overlayRef.current;
    const ctx = overlay?.getContext('2d');
    if (!canvas || !overlay || !ctx) return;
    if (overlay.width !== canvas.width) overlay.width = canvas.width;
    if (overlay.height !== canvas.height) overlay.height = canvas.height;
    ctx.clearRect(0, 0, overlay.width, overlay.height);
    ctx.fillStyle = 'rgba(66, 133, 244, 0.2)';
    ctx.strokeStyle = 'rgba(66, 133, 244, 0.9)';
    ctx.lineWidth = 2;
    ctx.fillRect(x - HOVER_BOX_W / 2, y - HOVER_BOX_H / 2, HOVER_BOX_W, HOVER_BOX_H);
    ctx.strokeRect(x - HOVER_BOX_W / 2, y - HOVER_BOX_H / 2, HOVER_BOX_W, HOVER_BOX_H);
  }

  function handleMouseDown(e: React.MouseEvent<HTMLCanvasElement>) {
    if (!isVisibleRef.current) return;
    const { x, y } = getCanvasCoords(e);
    if (inspectMode) {
      if (e.button === 0) onInspectClick?.(x, y);
      return;
    }
    sendJson({
      method: 'Input.dispatchMouseEvent',
      params: {
        type: 'mousePressed',
        x,
        y,
        button: cdpButton(e),
        clickCount: 1,
        modifiers: getModifiers(e),
      },
    });
  }

  function handleMouseUp(e: React.MouseEvent<HTMLCanvasElement>) {
    if (!isVisibleRef.current || inspectMode) return;
    const { x, y } = getCanvasCoords(e);
    sendJson({
      method: 'Input.dispatchMouseEvent',
      params: {
        type: 'mouseReleased',
        x,
        y,
        button: cdpButton(e),
        clickCount: 1,
        modifiers: getModifiers(e),
      },
    });
  }

  function handleMouseMove(e: React.MouseEvent<HTMLCanvasElement>) {
    if (!isVisibleRef.current) return;
    const { x, y } = getCanvasCoords(e);
    if (inspectMode) {
      drawHoverBox(x, y);
      return;
    }
    sendJson({
      method: 'Input.dispatchMouseEvent',
      params: {
        type: 'mouseMoved',
        x,
        y,
        button: 'none',
        clickCount: 0,
        modifiers: getModifiers(e),
      },
    });
  }

  // ------------------------------------------------------------------
  // Keyboard handlers
  // ------------------------------------------------------------------

  function handleKeyDown(e: React.KeyboardEvent<HTMLCanvasElement>) {
    if (!isVisibleRef.current) return;
    e.preventDefault();
    sendJson({
      method: 'Input.dispatchKeyEvent',
      params: {
        type: 'keyDown',
        key: e.key,
        code: e.code,
        modifiers: getModifiers(e),
      },
    });
  }

  function handleKeyUp(e: React.KeyboardEvent<HTMLCanvasElement>) {
    if (!isVisibleRef.current) return;
    sendJson({
      method: 'Input.dispatchKeyEvent',
      params: {
        type: 'keyUp',
        key: e.key,
        code: e.code,
        modifiers: getModifiers(e),
      },
    });
  }

  // ------------------------------------------------------------------
  // Wheel handler
  // ------------------------------------------------------------------

  function handleWheel(e: React.WheelEvent<HTMLCanvasElement>) {
    if (!isVisibleRef.current) return;
    e.preventDefault();
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const x = Math.round((e.clientX - rect.left) * scaleX);
    const y = Math.round((e.clientY - rect.top) * scaleY);
    sendJson({
      method: 'Input.dispatchMouseEvent',
      params: {
        type: 'mouseWheel',
        x,
        y,
        deltaX: e.deltaX,
        deltaY: e.deltaY,
        modifiers: getModifiers(e),
      },
    });
  }

  // ------------------------------------------------------------------
  // Touch handlers
  // ------------------------------------------------------------------

  function handleTouchStart(e: React.TouchEvent<HTMLCanvasElement>) {
    if (!isVisibleRef.current || inspectMode) return;
    e.preventDefault();
    const touch = e.touches[0];
    if (!touch) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const x = Math.round((touch.clientX - rect.left) * scaleX);
    const y = Math.round((touch.clientY - rect.top) * scaleY);
    sendJson({
      method: 'Input.dispatchMouseEvent',
      params: { type: 'mousePressed', x, y, button: 'left', clickCount: 1 },
    });
  }

  function handleTouchMove(e: React.TouchEvent<HTMLCanvasElement>) {
    if (!isVisibleRef.current || inspectMode) return;
    e.preventDefault();
    const touch = e.touches[0];
    if (!touch) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const x = Math.round((touch.clientX - rect.left) * scaleX);
    const y = Math.round((touch.clientY - rect.top) * scaleY);
    sendJson({
      method: 'Input.dispatchMouseEvent',
      params: { type: 'mouseMoved', x, y },
    });
  }

  function handleTouchEnd(e: React.TouchEvent<HTMLCanvasElement>) {
    if (!isVisibleRef.current || inspectMode) return;
    e.preventDefault();
    const canvas = canvasRef.current;
    if (!canvas) return;
    // changedTouches has the touch point that was lifted
    const touch = e.changedTouches[0];
    if (!touch) return;
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const x = Math.round((touch.clientX - rect.left) * scaleX);
    const y = Math.round((touch.clientY - rect.top) * scaleY);
    sendJson({
      method: 'Input.dispatchMouseEvent',
      params: { type: 'mouseReleased', x, y, button: 'left', clickCount: 1 },
    });
  }

  return (
    <div style={{ position: 'relative', width: '100%', height: '100%' }}>
      <canvas
        ref={canvasRef}
        role="img"
        aria-label="Remote browser display"
        tabIndex={0}
        style={{ width: '100%', height: '100%', display: 'block', cursor: inspectMode ? 'crosshair' : undefined }}
        onMouseDown={handleMouseDown}
        onMouseUp={handleMouseUp}
        onMouseMove={handleMouseMove}
        onKeyDown={handleKeyDown}
        onKeyUp={handleKeyUp}
        onWheel={handleWheel}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        onMouseLeave={inspectMode ? clearOverlay : undefined}
      />
      <canvas
        ref={overlayRef}
        data-testid="cdp-inspect-overlay"
        aria-hidden="true"
        style={{
          position: 'absolute', top: 0, left: 0, width: '100%', height: '100%',
          pointerEvents: 'none', display: inspectMode ? 'block' : 'none',
        }}
      />
      <div
        role="status"
        aria-live="polite"
        style={{ position: 'absolute', width: 1, height: 1, overflow: 'hidden', clip: 'rect(0,0,0,0)' }}
      >
        {connectionStatusText}
      </div>
    </div>
  );
}
